registryContract = w3.eth.contract(address=REGISTRY, abi=REGISTRY_ABI)

def getPublicKeyByProduct(productId: int, manufacturerAddress: str):
    manufacturer = to_checksum_address(manufacturerAddress)
    publicKey = registryContract.functions.getProductPublicKey(int(productId), manufacturer).call()
    return publicKey

def verifySignature(signature: bytes, productId: int, manufacturerAddress: str) -> bool:
    pubKeyHex = getPublicKeyByProduct(productId, manufacturerAddress)
    pubBytes = bytes.fromhex(pubKeyHex)

    v = signature[64]
    if v >= 27:
        v -= 27
    signature = signature[:64] + bytes([v])
    message = prepareMess(productId, manufacturerAddress)
    messPrefixed = getPrefixedMess(message)

    pubKey = keys.PublicKey.from_compressed_bytes(pubBytes)

    signature = keys.Signature(signature)
    is_valid = signature.verify_msg_hash(messPrefixed, pubKey)
    return is_valid
